1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { PageHeader, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
5	import { SuspendUserButton } from "@/components/AdminControls";
6	import { ImpersonateButton } from "@/components/admin/ImpersonateButton";
7	import { BulkTable, type BulkRow } from "@/components/admin/BulkTable";
8	import { bulkSuspendUsers } from "@/lib/actions-admin-billing";
9	import { paginate, pageHref } from "@/lib/pagination";
10	import { fleetMrrCents, currentRenewalPrices } from "@/lib/admin-metrics";
11	
12	export const dynamic = "force-dynamic";
13	
14	const PER_PAGE = 25;
15	
16	export default async function AdminUsers({
17	  searchParams,
18	}: {
19	  searchParams: Promise<{ q?: string; page?: string }>;
20	}) {
21	  // See the note on /admin/users/[id]: `clients` admits SUPPORT, but Impersonate
22	  // and Suspend are `requireAdmin()` actions. Render only what the role can use.
23	  const me = await requireArea("clients");
24	  const canAct = me.role === "ADMIN";
25	  const sp = await searchParams;
26	  const query = (sp.q ?? "").trim();
27	
28	  const where = query
29	    ? {
30	        OR: [
31	          { email: { contains: query, mode: "insensitive" as const } },
32	          { name: { contains: query, mode: "insensitive" as const } },
33	        ],
34	      }
35	    : undefined;
36	
37	  const total = await db.user.count({ where });
38	  const pg = paginate(sp, total, PER_PAGE);
39	  const [users, renewalPrices] = await Promise.all([
40	    db.user.findMany({
41	    where,
42	    include: {
43	      servers: {
44	        where: { status: { notIn: ["DELETING"] } },
45	        select: {
46	          isFree: true,
47	          status: true,
48	          termMonths: true,
49	          extraDiskGB: true,
50	          backupTier: true,
51	          annualDiscountPct: true,
52	          plan: { select: { name: true, priceCents: true } },
53	          gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
54	          // Needed by renewalCharge (via serverMonthlyCents) to price that add-on.
55	          dedicatedIp: { select: { id: true } },
56	          wantsDedicatedIp: true,
57	          grandfatheredRenewalCents: true,
58	        },
59	      },
60	    },
61	    orderBy: { createdAt: "desc" },
62	    skip: pg.skip,
63	    take: pg.take,
64	    }),
65	    currentRenewalPrices(),
66	  ]);
67	
68	  const exportHref = `/api/admin/export?type=users${query ? `&q=${encodeURIComponent(query)}` : ""}`;
69	
70	  const rows: BulkRow[] = users.map((u) => {
71	    const mrr = fleetMrrCents(u.servers, renewalPrices);
72	    return {
73	      id: u.id,
74	      selectable: u.role !== "ADMIN",
75	      cells: [
76	        <span key="c">
77	          <Link
78	            href={`/admin/users/${u.id}`}
79	            className={`font-medium hover:text-brand-300 ${mrr > 0 ? "text-emerald-300" : ""}`}
80	            title={mrr > 0 ? `Paying customer — ${fmtMoney(mrr)}/mo` : undefined}
81	          >
82	            {u.name}
83	          </Link>
84	          <span className="ml-2 text-xs text-slate-500">{u.email}</span>
85	          {u.suspended && (
86	            <span className="ml-2">
87	              <Badge tone="red">suspended</Badge>
88	            </span>
89	          )}
90	        </span>,
91	        <Badge key="r" tone={u.role === "ADMIN" ? "brand" : "slate"}>{u.role.toLowerCase()}</Badge>,
92	        u.servers.length,
93	        fmtMoney(u.balanceCents),
94	        mrr > 0 ? `${fmtMoney(mrr)}/mo` : <span key="m" className="text-slate-500">—</span>,
95	        <span key="j" className="text-xs text-slate-400">{timeAgo(u.createdAt)}</span>,
96	        <div key="a" className="flex items-center justify-end gap-2">
97	          <Link href={`/admin/users/${u.id}`} className="btn-ghost py-1 text-xs">
98	            View →
99	          </Link>
100	          {canAct && u.role !== "ADMIN" && <ImpersonateButton userId={u.id} email={u.email} small />}
101	          {canAct && u.role !== "ADMIN" && <SuspendUserButton userId={u.id} suspended={u.suspended} />}
102	        </div>,
103	      ],
104	    };
105	  });
106	
107	  return (
108	    <div className="space-y-6">
109	      <PageHeader title="Clients" sub={`${total} account${total === 1 ? "" : "s"}${query ? ` matching “${query}”` : ""}`}>
110	        <form method="GET" className="flex items-center gap-2">
111	          <input
112	            className="input w-64 py-2"
113	            type="search"
114	            name="q"
115	            placeholder="Search email or name…"
116	            defaultValue={query}
117	          />
118	          <button className="btn-secondary py-2">Search</button>
119	          {query && (
120	            <Link href="/admin/users" className="btn-ghost py-2 text-xs">
121	              Clear
122	            </Link>
123	          )}
124	        </form>
125	      </PageHeader>
126	
127	      <div className="card p-0">
128	        <BulkTable
129	          columns={[
130	            { header: "Client" },
131	            { header: "Role" },
132	            { header: "Servers" },
133	            { header: "Balance" },
134	            { header: "Monthly spend" },
135	            { header: "Joined" },
136	            { header: "Actions", className: "text-right" },
137	          ]}
138	          rows={rows}
139	          exportHref={exportHref}
140	          minWidth={860}
141	          empty="No clients match this search."
142	          actions={
143	            canAct
144	              ? [
145	                  {
146	                    label: "Suspend",
147	                    danger: true,
148	                    // State the consequence, not the verb. Suspension logs the
149	                    // account out immediately and blocks sign-in; their servers
150	                    // keep running and keep costing us until someone unsuspends.
151	                    confirm:
152	                      "Suspend the selected clients?\n\nEach one is signed out immediately and cannot log back in until unsuspended. Their servers keep running and are not touched.",
153	                    run: bulkSuspendUsers,
154	                  },
155	                ]
156	              : []
157	          }
158	        />
159	
160	        <div className="flex items-center justify-between gap-3 px-5 py-4 text-xs text-slate-500">
161	          <span>
162	            Page {pg.page} of {pg.pages} · {total} client{total === 1 ? "" : "s"}
163	          </span>
164	          <div className="flex items-center gap-2">
165	            {pg.page > 1 && (
166	              <Link href={pageHref("/admin/users", { q: query }, pg.page - 1)} className="btn-ghost py-1 text-xs">
167	                ← Prev
168	              </Link>
169	            )}
170	            {pg.page < pg.pages && (
171	              <Link href={pageHref("/admin/users", { q: query }, pg.page + 1)} className="btn-ghost py-1 text-xs">
172	                Next →
173	              </Link>
174	            )}
175	          </div>
176	        </div>
177	      </div>
178	
179	      <p className="text-xs text-slate-500">
180	        Wallet credits are issued from a client&apos;s profile page. Monthly spend is the committed MRR of the
181	        client&apos;s active paid servers. Select rows to bulk-suspend or export the filtered set to CSV.
182	      </p>
183	    </div>
184	  );
185	}
