1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { ServerStatus } from "@prisma/client";
5	import { PageHeader, StatusDot, Badge, fmtMoney, fmtBytes } from "@/components/ui/primitives";
6	import { MeterBar } from "@/components/ui/charts";
7	import { monthlyCents } from "@/lib/admin-metrics";
8	import { SuspendServerButton, ReconcileServerButton } from "@/components/AdminControls";
9	import { AutoRefresh } from "@/components/AutoRefresh";
10	import { pveForNode, listVms } from "@/lib/proxmox";
11	import { REGION_LABELS } from "@/lib/node-regions";
12	
13	export const dynamic = "force-dynamic";
14	
15	const STATUSES = Object.values(ServerStatus);
16	const TRANSITIONAL: ServerStatus[] = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"];
17	
18	export default async function AdminServers({
19	  searchParams,
20	}: {
21	  searchParams: Promise<{ status?: string }>;
22	}) {
23	  await requireArea("fleet");
24	  const { status } = await searchParams;
25	  const statusFilter = STATUSES.includes(status as ServerStatus) ? (status as ServerStatus) : undefined;
26	
27	  const [servers, counts] = await Promise.all([
28	    db.server.findMany({
29	      where: statusFilter ? { status: statusFilter } : undefined,
30	      include: {
31	        user: { select: { id: true, email: true } },
32	        plan: { select: { name: true, priceCents: true } },
33	        gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
34	        node: { select: { id: true, name: true, region: true, publicIp: true, apiUrl: true, pveNode: true, tokenId: true, tokenSecret: true } },
35	      },
36	      orderBy: { createdAt: "desc" },
37	    }),
38	    db.server.groupBy({ by: ["status"], _count: true }),
39	  ]);
40	
41	  const countByStatus = new Map(counts.map((c) => [c.status, c._count]));
42	  const total = counts.reduce((n, c) => n + c._count, 0);
43	  const anyTransitional = servers.some((s) => TRANSITIONAL.includes(s.status));
44	
45	  // Live resource metrics, one Proxmox call PER NODE (not per server) — /qemu
46	  // on a node returns every VM's current cpu/mem in one shot, so this stays
47	  // cheap regardless of how many servers are in the fleet. A node's API being
48	  // slow/unreachable only blanks out ITS OWN servers' metrics column, same
49	  // "one node down doesn't take the others with it" discipline as the
50	  // Infrastructure page.
51	  const nodesById = new Map(servers.map((s) => s.node).filter((n): n is NonNullable<typeof n> => !!n).map((n) => [n.id, n]));
52	  const liveByNode = new Map(
53	    await Promise.all(
54	      Array.from(nodesById.values()).map(async (n) => {
55	        try {
56	          const vms = await listVms(pveForNode(n));
57	          const byVmid = new Map(vms.map((v: any) => [v.vmid, v]));
58	          return [n.id, byVmid] as const;
59	        } catch {
60	          return [n.id, null] as const;
61	        }
62	      }),
63	    ),
64	  );
65	
66	  return (
67	    <div className="space-y-6">
68	      {anyTransitional && <AutoRefresh />}
69	      <PageHeader title="Server fleet" sub={`${total} server${total === 1 ? "" : "s"} across all clients.`} />
70	
71	      {/* Status filter chips */}
72	      <div className="flex flex-wrap items-center gap-2">
73	        <Link
74	          href="/admin/servers"
75	          className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
76	            !statusFilter
77	              ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
78	              : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
79	          }`}
80	        >
81	          All · {total}
82	        </Link>
83	        {STATUSES.filter((s) => countByStatus.has(s)).map((s) => (
84	          <Link
85	            key={s}
86	            href={`/admin/servers?status=${s}`}
87	            className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
88	              statusFilter === s
89	                ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
90	                : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
91	            }`}
92	          >
93	            {s.toLowerCase().replace(/_/g, " ")} · {countByStatus.get(s)}
94	          </Link>
95	        ))}
96	      </div>
97	
98	      <div className="card overflow-x-auto p-0">
99	        <table className="table-shell min-w-[1500px]">
100	          <thead>
101	            <tr>
102	              <th>Hostname</th>
103	              <th>Owner</th>
104	              <th>Plan</th>
105	              <th>VMID</th>
106	              <th>SSH endpoint</th>
107	              <th>Node</th>
108	              <th>Region</th>
109	              <th className="min-w-40">Resources</th>
110	              <th>Status</th>
111	              <th>Expires</th>
112	              <th className="text-right">Actions</th>
113	            </tr>
114	          </thead>
115	          <tbody>
116	            {servers.length === 0 && (
117	              <tr>
118	                <td colSpan={11} className="py-10 text-center text-slate-500">
119	                  No servers{statusFilter ? ` in status ${statusFilter.toLowerCase()}` : " yet"}.
120	                </td>
121	              </tr>
122	            )}
123	            {servers.map((s) => (
124	              <tr key={s.id}>
125	                <td>
126	                  <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
127	                    {s.hostname}
128	                  </Link>
129	                  {s.isFree && (
130	                    <span className="ml-2">
131	                      <Badge tone="green">free</Badge>
132	                    </span>
133	                  )}
134	                </td>
135	                <td>
136	                  <Link href={`/admin/users/${s.user.id}`} className="text-slate-300 hover:text-brand-300">
137	                    {s.user.email}
138	                  </Link>
139	                </td>
140	                <td>
141	                  {s.gamePlan ? s.gamePlan.name : s.plan.name}
142	                  {!s.isFree && (
143	                    <span className="text-xs text-slate-500">
144	                      {" "}
145	                      ·{" "}
146	                      {fmtMoney(s.gamePlan ? monthlyCents(s.gamePlan.priceCents, s.gamePlan.termMonths) : s.plan.priceCents)}
147	                      /mo
148	                    </span>
149	                  )}
150	                </td>
151	                <td className="font-mono text-xs">{s.vmid ?? "—"}</td>
152	                <td className="font-mono text-xs">
153	                  {/* The CONNECTABLE endpoint: NAT servers reach the VM through the node's
154	                      PUBLIC ip + the forwarded ssh port — never the internal 10.20.x.x
155	                      address (that's unreachable from outside the host). Show the public
156	                      endpoint like the customer dashboard does; keep the internal ip as a
157	                      muted secondary line for admin NAT debugging. */}
158	                  {s.sshPort ? (
159	                    <>
160	                      <span>{`${s.node?.publicIp ?? process.env.PUBLIC_IP ?? "—"}:${s.sshPort}`}</span>
161	                      {s.ipAddress && <div className="text-slate-600">int {s.ipAddress}</div>}
162	                    </>
163	                  ) : (
164	                    s.ipAddress ?? "—"
165	                  )}
166	                </td>
167	                <td className="text-xs">
168	                  {s.node ? (
169	                    <Link href={`/admin/nodes/${s.node.id}`} className="hover:text-brand-300">
170	                      {s.node.name}
171	                    </Link>
172	                  ) : (
173	                    "—"
174	                  )}
175	                </td>
176	                <td className="text-xs text-slate-400">{s.node ? REGION_LABELS[s.node.region] ?? s.node.region : "—"}</td>
177	                <td>
178	                  {(() => {
179	                    const live = s.vmid && s.node ? liveByNode.get(s.node.id)?.get(s.vmid) : null;
180	                    if (!live) {
181	                      return <span className="text-xs text-slate-600">{s.vmid ? "unavailable" : "—"}</span>;
182	                    }
183	                    const cpuPct = Math.round((live.cpu ?? 0) * 100);
184	                    const memRatio = live.maxmem > 0 ? live.mem / live.maxmem : 0;
185	                    return (
186	                      <div className="space-y-1.5">
187	                        <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500">
188	                          <span>CPU</span>
189	                          <span className="font-mono">{cpuPct}%</span>
190	                        </div>
191	                        <MeterBar value={cpuPct} max={100} color={cpuPct > 90 ? "#ef4444" : cpuPct > 75 ? "#f59e0b" : "#34d399"} />
192	                        <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500">
193	                          <span>RAM</span>
194	                          <span className="font-mono">
195	                            {fmtBytes(live.mem)} / {fmtBytes(live.maxmem)}
196	                          </span>
197	                        </div>
198	                        <MeterBar
199	                          value={live.mem}
200	                          max={live.maxmem || 1}
201	                          color={memRatio > 0.9 ? "#ef4444" : memRatio > 0.75 ? "#f59e0b" : "#34d399"}
202	                        />
203	                      </div>
204	                    );
205	                  })()}
206	                </td>
207	                <td>
208	                  <StatusDot status={s.status} />
209	                </td>
210	                <td className="text-xs">
211	                  {s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
212	                </td>
213	                <td className="text-right">
214	                  <div className="flex items-center justify-end gap-2">
215	                    {(["ERROR", "PENDING", "PROVISIONING"] as ServerStatus[]).includes(s.status) && (
216	                      <ReconcileServerButton serverId={s.id} />
217	                    )}
218	                    {s.status !== "DELETING" && (
219	                      <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />
220	                    )}
221	                  </div>
222	                </td>
223	              </tr>
224	            ))}
225	          </tbody>
226	        </table>
227	      </div>
228	    </div>
229	  );
230	}
