import { db } from "@/lib/db";

async function main() {
  const totalUsers = await db.user.count();
  const withHeard = await db.user.count({ where: { heardAboutUs: { not: null } } });
  const withHeardSkipped = await db.user.count({ where: { heardAboutUs: "skipped" } });

  // How many users have at least one authenticated Visit row (so we know their visitorId)?
  const usersWithVisit = await db.visit.findMany({
    where: { userId: { not: null } },
    distinct: ["userId"],
    select: { userId: true },
  });
  console.log("total users:", totalUsers);
  console.log("users with heardAboutUs answered (incl skipped):", withHeard, "of which skipped:", withHeardSkipped);
  console.log("distinct users with >=1 authenticated Visit row:", usersWithVisit.length);

  // For those users, get their visitorIds
  const userIds = usersWithVisit.map((v) => v.userId!).filter(Boolean);
  const visitorLinks = await db.visit.findMany({
    where: { userId: { in: userIds }, visitorId: { not: null } },
    select: { userId: true, visitorId: true },
    distinct: ["userId", "visitorId"],
  });
  const visitorIdsByUser = new Map<string, Set<string>>();
  for (const v of visitorLinks) {
    if (!v.userId || !v.visitorId) continue;
    if (!visitorIdsByUser.has(v.userId)) visitorIdsByUser.set(v.userId, new Set());
    visitorIdsByUser.get(v.userId)!.add(v.visitorId);
  }
  console.log("users with a known visitorId cookie:", visitorIdsByUser.size);

  const allVisitorIds = Array.from(new Set(visitorLinks.map((v) => v.visitorId!)));
  const utmVisits = await db.visit.findMany({
    where: {
      visitorId: { in: allVisitorIds },
      OR: [{ utmSource: { not: null } }, { gclid: { not: null } }],
    },
    select: { visitorId: true, utmSource: true, utmMedium: true, utmCampaign: true, gclid: true, createdAt: true },
    orderBy: { createdAt: "asc" },
  });
  const utmByVisitorId = new Map<string, (typeof utmVisits)[number]>();
  for (const v of utmVisits) {
    if (!v.visitorId) continue;
    if (!utmByVisitorId.has(v.visitorId)) utmByVisitorId.set(v.visitorId, v); // first (earliest) wins
  }
  console.log("distinct visitorIds with any utm/gclid-tagged visit:", utmByVisitorId.size);

  let usersWithDerivedAttribution = 0;
  for (const [, vids] of visitorIdsByUser) {
    for (const vid of vids) {
      if (utmByVisitorId.has(vid)) {
        usersWithDerivedAttribution++;
        break;
      }
    }
  }
  console.log("users for whom we could derive a real utm/gclid first-touch via visitorId join:", usersWithDerivedAttribution);
  console.log("out of total users:", totalUsers);

  // referrer fallback stats
  const totalVisits = await db.visit.count();
  const visitsWithReferrer = await db.visit.count({ where: { referrer: { not: null } } });
  console.log("total Visit rows:", totalVisits, "with a referrer:", visitsWithReferrer);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

