import { db } from "@/lib/db";

async function main() {
  // Sample a game server and inspect its owner's wallet transactions to see if
  // the initial "Game server: ..." debit really lacks the hostname, and whether
  // its createdAt lines up exactly with the server's own createdAt (same tx).
  const gameServer = await db.server.findFirst({
    where: { gamePlanId: { not: null } },
    select: { id: true, hostname: true, userId: true, createdAt: true },
    orderBy: { createdAt: "asc" },
  });
  console.log("sample game server:", gameServer);
  if (gameServer) {
    const txs = await db.walletTransaction.findMany({
      where: { userId: gameServer.userId },
      select: { description: true, amountCents: true, createdAt: true },
      orderBy: { createdAt: "asc" },
    });
    for (const t of txs) {
      const sameInstant = t.createdAt.getTime() === gameServer.createdAt.getTime();
      const hasHostname = t.description.includes(gameServer.hostname);
      console.log(
        t.createdAt.toISOString(),
        t.amountCents,
        JSON.stringify(t.description),
        "sameInstantAsServer:",
        sameInstant,
        "hasHostname:",
        hasHostname,
      );
    }
  }

  // Also check a VPS server + its invoices, to confirm hostname coverage there.
  const vpsServer = await db.server.findFirst({
    where: { gamePlanId: null, isFree: false },
    select: { id: true, hostname: true, userId: true, createdAt: true },
    orderBy: { createdAt: "asc" },
  });
  console.log("\nsample vps server:", vpsServer);
  if (vpsServer) {
    const invs = await db.invoice.findMany({
      where: { userId: vpsServer.userId },
      select: { description: true, amountCents: true, refundedCents: true, status: true, createdAt: true },
      orderBy: { createdAt: "asc" },
    });
    for (const i of invs) {
      console.log(i.createdAt.toISOString(), i.status, i.amountCents, i.refundedCents, JSON.stringify(i.description), "hasHostname:", i.description.includes(vpsServer.hostname));
    }
  }
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

