import { db } from "@/lib/db";

/**
 * Real, historical lifetime revenue for a specific server — including
 * add-ons, upgrades and renewals, net of refunds. NOT an estimate (never
 * current-plan-price × months-elapsed): every cent comes from actual billing
 * records this app already writes.
 *
 * There is no direct FK from Invoice/WalletTransaction to Server — every
 * charge site (lib/order.ts, lib/game-order.ts, worker/billing.ts, lib/resize.ts,
 * lib/dedicated-ip-purchase.ts, lib/disk-expand.ts, lib/backup-upgrade.ts,
 * lib/game-resize.ts, lib/actions-server-lifecycle.ts) instead embeds the
 * server's `hostname` in the Invoice/WalletTransaction `description` string —
 * the exact same convention `lib/actions-billing.ts`'s `regenerateMissingInvoices`
 * already relies on (`description: { contains: server.hostname }`). This module
 * follows that same convention, scoped additionally by `userId` (a server's
 * hostname is unique to begin with, but scoping by owner removes any residual
 * cross-customer collision risk entirely).
 *
 * Primary source: Invoice, because it is the actual billing document (what the
 * customer sees on /dashboard/invoices, tax-inclusive) and — verified against
 * production data — has hostname coverage for every charge type: the initial
 * order (VPS AND game), renewals, upgrades, and every add-on (dedicated IP,
 * disk, backups). PAID invoices net their own `refundedCents` (an admin
 * partial/full refund via `refundPayment` updates the SAME invoice, never
 * creates a new one); a small number of cancellations issue a separate
 * "credit note" invoice with `status: "REFUNDED"` and a positive `amountCents`
 * (see `actions-server-lifecycle.ts`'s immediate-cancel refund) — those are
 * subtracted.
 *
 * Known, verified gap this module corrects for: a mid-term DOWNGRADE credit
 * (`actions-server-lifecycle.ts`, "Downgrade to … (prorated credit)") and a
 * job-failure refund (worker/index.ts, "Refund: failed …") both only touch
 * WalletTransaction — no Invoice is written or adjusted for either. Both are
 * folded in as corrections below so they are not silently missed. (A downgrade
 * credit that is later clawed back on a failed resize — "Reversed downgrade
 * credit …" — is included too, so the two net to zero exactly as they do in
 * the customer's real wallet balance.)
 *
 * Separately verified and NOT correctable here without touching live billing
 * data: the very first WalletTransaction line for a GAME server order
 * (lib/game-order.ts, `Game server: <plan> (<family>) — <term>`) omits the
 * hostname — unlike every sibling call site. It doesn't matter for this
 * module (Invoice is primary and DOES carry the hostname for that same
 * charge), but it means that one line is invisible to anything that reads
 * WalletTransaction by hostname text (e.g. a future admin tool built the way
 * `regenerateMissingInvoices` was). Worth a one-line fix; flagged separately.
 */
export async function resolveServerLifetimeSpendCents(
  servers: { id: string; hostname: string; userId: string }[],
): Promise<Map<string, number>> {
  const result = new Map<string, number>();
  if (servers.length === 0) return result;

  const userIds = Array.from(new Set(servers.map((s) => s.userId)));

  const [invoices, corrections] = await Promise.all([
    db.invoice.findMany({
      where: { userId: { in: userIds }, status: { in: ["PAID", "REFUNDED"] } },
      select: { userId: true, description: true, amountCents: true, refundedCents: true, status: true },
    }),
    db.walletTransaction.findMany({
      where: {
        userId: { in: userIds },
