"use client";

import { useMemo, useState } from "react";
import type { ReactNode } from "react";

export type FleetColumn = { header: ReactNode; className?: string };
export type FleetRow = { id: string; cells: ReactNode[]; search: string };

/**
 * Client-side search over the Server Fleet table. The whole fleet (33 servers
 * fleet-wide at the time this was built) is already loaded onto the page in
 * one query — a client-side filter over rows already in memory is instant and
 * needs no round trip, and stays correct as the fleet grows into the low
 * hundreds. Revisit (server-side query + pagination, like /admin/users) if
 * the fleet ever grows enough that loading every row up front stops being
 * cheap.
 *
 * The search box matches hostname, owner (name/email), plan/service name, and
 * node — combinable with the page's own status filter chips (those already
 * re-query the server; this only filters whatever set that query returned).
 */
export function ServerFleetTable({
  columns,
  rows,
  minWidth = 1500,
  empty = "No servers match this search.",
}: {
  columns: FleetColumn[];
  rows: FleetRow[];
  minWidth?: number;
  empty?: string;
}) {
  const [q, setQ] = useState("");

  const filtered = useMemo(() => {
    const needle = q.trim().toLowerCase();
    if (!needle) return rows;
    return rows.filter((r) => r.search.includes(needle));
  }, [q, rows]);

  return (
    <div className="space-y-3">
      <div className="flex items-center gap-2 px-1">
        <input
          className="input w-80 py-2"
          type="search"
          placeholder="Search hostname, owner, plan, or node…"
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
        <span className="text-xs text-slate-500">
          {q ? `${filtered.length} of ${rows.length} servers` : `${rows.length} servers`}
        </span>
      </div>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell" style={{ minWidth }}>
          <thead>
            <tr>
              {columns.map((c, i) => (
                <th key={i} className={c.className}>
                  {c.header}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.length === 0 && (
              <tr>
                <td colSpan={columns.length} className="py-10 text-center text-slate-500">
                  {empty}
                </td>
              </tr>
            )}
            {filtered.map((row) => (
              <tr key={row.id}>
                {row.cells.map((cell, i) => (
                  <td key={i} className={columns[i]?.className}>
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

