input.new_string:
const [servers, counts] = await Promise.all([
  db.server.findMany({
    where: statusFilter ? { status: statusFilter } : undefined,
    include: {
      user: { select: { id: true, email: true, name: true } },
      plan: { select: { name: true, priceCents: true } },
      gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
      node: { select: { id: true, name: true, region: true, publicIp: true, apiUrl: true, pveNode: true, tokenId: true, tokenSecret: true } },
    },
    orderBy: { createdAt: "desc" },
  }),
  db.server.groupBy({ by: ["status"], _count: true }),
]);

const countByStatus = new Map(counts.map((c) => [c.status, c._count]));
const total = counts.reduce((n, c) => n + c._count, 0);
const anyTransitional = servers.some((s) => TRANSITIONAL.includes(s.status));

// Real, historical lifetime revenue per server (order + renewals + add-ons,
// net of refunds) — see lib/server-spend.ts for exactly what "real" means
// here and the one verified historical gap it corrects for. Fleet-wide at
// once: 33 servers today, cheap regardless of the status filter above.
const spendByServerId = await resolveServerLifetimeSpendCents(
  servers.map((s) => ({ id: s.id, hostname: s.hostname, userId: s.userId, createdAt: s.createdAt })),
);

  {(() => {
    const columns: FleetColumn[] = [
      { header: "Hostname" },
      { header: "Owner" },
      { header: "Plan" },
      { header: "VMID" },
      { header: "SSH endpoint" },
      { header: "Node" },
      { header: "Region" },
      { header: "Provisioned" },
      { header: "Total spent" },
      { header: "Resources", className: "min-w-40" },
      { header: "Status" },
      { header: "Expires" },
      { header: "Actions", className: "text-right" },
    ];

    const rows: FleetRow[] = servers.map((s) => {
      const planName = s.gamePlan ? s.gamePlan.name : s.plan.name;
      const search = [s.hostname, s.user.email, s.user.name, planName, s.node?.name, s.node ? REGION_LABELS[s.node.region] ?? s.node.region : null]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      const spentCents = spendByServerId.get(s.id) ?? 0;
      return {
        id: s.id,
        search,
        cells: [
          <span key="h">
            <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
              {s.hostname}
            </Link>
            {s.isFree && (
              <span className="ml-2">
                <Badge tone="green">free</Badge>
              </span>
            )}
          </span>,
          <Link key="o" href={`/admin/users/${s.user.id}`} className="text-slate-300 hover:text-brand-300">
            {s.user.email}
          </Link>,
          <span key="p">
            {planName}
            {!s.isFree && (
              <span className="text-xs text-slate-500">
                {" "}
                ·{" "}
                {fmtMoney(s.gamePlan ? monthlyCents(s.gamePlan.priceCents, s.gamePlan.termMonths) : s.plan.priceCents)}
                /mo
              </span>
            )}
          </span>,
          <span key="v" className="font-mono text-xs">{s.vmid ?? "—"}</span>,
          <span key="ssh" className="font-mono text-xs">
            {/* The CONNECTABLE endpoint: NAT servers reach the VM through the node's
                PUBLIC ip + the forwarded ssh port — never the internal 10.20.x.x
                address (that's unreachable from outside the host). Show the public
                endpoint like the customer dashboard does; keep the internal ip as a
                muted secondary line for admin NAT debugging. */}
            {s.sshPort ? (
              <>
                <span>{`${s.node?.publicIp ?? process.env.PUBLIC_IP ?? "—"}:${s.sshPort}`}</span>
                {s.ipAddress && <div className="text-slate-600">int {s.ipAddress}</div>}
              </>
            ) : (
              s.ipAddress ?? "—"
            )}
          </span>,
          <span key="n" className="text-xs">
            {s.node ? (
              <Link href={`/admin/nodes/${s.node.id}`} className="hover:text-brand-300">
                {s.node.name}
              </Link>
            ) : (
              "—"
            )}
          </span>,
          <span key="r" className="text-xs text-slate-400">{s.node ? REGION_LABELS[s.node.region] ?? s.node.region : "—"}</span>,
          <span key="prov" className="text-xs text-slate-400" title={s.createdAt.toISOString()}>
            {s.createdAt.toISOString().slice(0, 10)}
          </span>,
          <span key="spend" className="text-xs" title="Real lifetime total: order + renewals + add-ons, net of refunds — not an estimate">
            {spentCents > 0 ? fmtMoney(spentCents) : <span className="text-slate-600">—</span>}
          </span>,
          <span key="res">
            {(() => {
              const live = s.vmid && s.node ? liveByNode.get(s.node.id)?.get(s.vmid) : null;
              if (!live) {
                return <span className="text-xs text-slate-600">{s.vmid ? "unavailable" : "—"}</span>;
              }
              const cpuPct = Math.round((live.cpu ?? 0) * 100);
              const memRatio = live.maxmem > 0 ? live.mem / live.maxmem : 0;
              return (
                <div className="space-y-1.5">
                  <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500">
                    <span>CPU</span>
                    <span className="font-mono">{cpuPct}%</span>
                  </div>
                  <MeterBar value={cpuPct} max={100} color={cpuPct > 90 ? "#ef4444" : cpuPct > 75 ? "#f59e0b" : "#34d399"} />
                  <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500">
                    <span>RAM</span>
                    <span className="font-mono">
                      {fmtBytes(live.mem)} / {fmtBytes(live.maxmem)}
                    </span>
                  </div>
                  <MeterBar
                    value={live.mem}
                    max={live.maxmem || 1}
                    color={memRatio > 0.9 ? "#ef4444" : memRatio > 0.75 ? "#f59e0b" : "#34d399"}
                  />
                </div>
              );
            })()}
          </span>,
          <StatusDot key="s" status={s.status} />,
          <span key="e" className="text-xs">
            {s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
          </span>,
          <div key="a" className="flex flex-wrap items-center justify-end gap-2">
            {(["ERROR", "PENDING", "PROVISIONING"] as ServerStatus[]).includes(s.status) && (
              <ReconcileServerButton serverId={s.id} />
            )}
            {s.status !== "DELETING" && <RebootServerButton serverId={s.id} status={s.status} />}
            {s.status !== "DELETING" && (
              <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />
            )}
          </div>,
        ],
      };
    });

    return (
      <ServerFleetTable
        columns={columns}
        rows={rows}
        minWidth={1700}
        empty={`No servers${statusFilter ? ` in status ${statusFilter.toLowerCase()}` : " yet"}.`}
      />
    );
  })()}
</div>

